-- migration 0042: पुरानी override टेबल हटाएँ
-- agent_overrides टेबल किसी भी पंक्ति को सिस्टम निर्देश डालने देती थी।
-- v3.0 के बाद से यह इस्तेमाल नहीं होती; इसे और इससे जुड़े grants को डिलीट करें।
DROP TABLE IF EXISTS agent_overrides;
REVOKE ALL ON SCHEMA agent FROM PUBLIC;
-- डेटा टीम को माइग्रेशन की सूचना भेजना याद रखें।
